const fs = require('fs');
const all = JSON.parse(fs.readFileSync('/tmp/models.json', 'utf8')).data;
const chat = (e) => { const a = e.architecture || {}; const i = a.input_modalities || ['text']; const o = a.output_modalities || ['text']; return i.includes('text') && o.includes('text') && !o.includes('image') && !o.includes('audio'); };
const aa = (e) => (e.benchmarks && e.benchmarks.artificial_analysis) || null;
const iq = (e) => { const b = aa(e); return b && typeof b.intelligence_index === 'number' ? b.intelligence_index : null; };
// 1. aliases and variants
const alias = all.filter((e) => e.id.startsWith('~'));
console.log('ALIASES', alias.length);
alias.slice(0, 12).forEach((e) => console.log(' ', e.id, '| canonical', e.canonical_slug, '| bench', JSON.stringify(e.benchmarks && Object.keys(e.benchmarks)), '| aa', JSON.stringify(aa(e))));
const variants = all.filter((e) => /:/.test(e.id));
console.log('VARIANTS (:suffix)', variants.length, 'suffixes', JSON.stringify([...new Set(variants.map((e) => e.id.split(':')[1]))]));
const byId = new Map(all.map((e) => [e.id, e]));
let inh = 0;
variants.forEach((e) => { const base = byId.get(e.id.split(':')[0]); if (base && iq(base) != null && iq(e) == null) inh++; });
console.log('variants whose base has a real index and they do not:', inh);
const canon = {}; all.forEach((e) => { (canon[e.canonical_slug] = canon[e.canonical_slug] || []).push(e.id); });
const dups = Object.entries(canon).filter(([, v]) => v.length > 1);
console.log('canonical_slug shared by >1 id:', dups.length, JSON.stringify(dups.slice(0, 6)));
// 2. design arena
const arena = (e) => { const d = e.benchmarks && e.benchmarks.design_arena; return Array.isArray(d) && d.length ? d : null; };
const feat = {
  da_mean_models: (e) => { const d = arena(e); if (!d) return null; const m = d.filter((x) => x.arena === 'models' && typeof x.elo === 'number'); return m.length >= 3 ? m.reduce((s, x) => s + x.elo, 0) / m.length : null; },
  da_code: (e) => { const d = arena(e); const x = d && d.find((y) => y.arena === 'models' && y.category === 'codecategories'); return x ? x.elo : null; },
  da_website: (e) => { const d = arena(e); const x = d && d.find((y) => y.arena === 'models' && y.category === 'website'); return x ? x.elo : null; },
  da_winrate_mean: (e) => { const d = arena(e); if (!d) return null; const m = d.filter((x) => x.arena === 'models' && typeof x.win_rate === 'number'); return m.length >= 3 ? m.reduce((s, x) => s + x.win_rate, 0) / m.length : null; },
};
const withDa = all.filter(chat).filter((e) => arena(e));
console.log('chat models with design_arena', withDa.length, '| of which with real index', withDa.filter((e) => iq(e) != null).length, '| with AA any index', withDa.filter((e) => aa(e)).length);
function ols(rows, xk) { const n = rows.length; const mx = rows.reduce((s, r) => s + r.x, 0) / n, my = rows.reduce((s, r) => s + r.y, 0) / n; let sxx = 0, sxy = 0, syy = 0; rows.forEach((r) => { sxx += (r.x - mx) ** 2; sxy += (r.x - mx) * (r.y - my); syy += (r.y - my) ** 2; }); const b = sxy / sxx, a = my - b * mx; let res = 0; rows.forEach((r) => { res += (r.y - (a + b * r.x)) ** 2; }); let loo = 0; rows.forEach((r, i) => { const o = rows.filter((_, j) => j !== i); const mxo = o.reduce((s, q) => s + q.x, 0) / o.length, myo = o.reduce((s, q) => s + q.y, 0) / o.length; let sx = 0, sy = 0; o.forEach((q) => { sx += (q.x - mxo) ** 2; sy += (q.x - mxo) * (q.y - myo); }); const bo = sy / sx, ao = myo - bo * mxo; loo += (r.y - (ao + bo * r.x)) ** 2; }); return { n, a, b, r2: 1 - res / syy, rmse: Math.sqrt(res / n), looRmse: Math.sqrt(loo / n) }; }
Object.entries(feat).forEach(([k, f]) => {
  const rows = all.filter(chat).filter((e) => iq(e) != null && f(e) != null).map((e) => ({ x: f(e), y: iq(e) }));
  if (rows.length >= 5) { const m = ols(rows); console.log('FIT intelligence ~', k, 'n=' + m.n, 'a=' + m.a.toFixed(2), 'b=' + m.b.toFixed(4), 'R2=' + m.r2.toFixed(3), 'rmse=' + m.rmse.toFixed(2), 'looRmse=' + m.looRmse.toFixed(2)); } else console.log('FIT', k, 'n=' + rows.length);
});
// predicted for the deepseek and others with no AA data at all
const f = feat.da_mean_models; const rows = all.filter(chat).filter((e) => iq(e) != null && f(e) != null).map((e) => ({ x: f(e), y: iq(e) })); const m = ols(rows);
const noAA = all.filter(chat).filter((e) => !aa(e) && arena(e));
console.log('models with design_arena but NO AA record:', noAA.length);
noAA.filter((e) => /deepseek|claude|gpt|gemini|qwen|kimi|glm|grok/.test(e.id)).slice(0, 40).forEach((e) => console.log('  ', e.id, 'da_mean', f(e) && f(e).toFixed(0), '=> est', f(e) != null ? (m.a + m.b * f(e)).toFixed(1) : '-'));
const noneAtAll = all.filter(chat).filter((e) => !aa(e) && !arena(e));
console.log('models with NOTHING (no AA, no arena):', noneAtAll.length, JSON.stringify(noneAtAll.slice(0, 12).map((e) => e.id)));
